UPDATE org01_code
   SET org01_org_cd       = #{orgCd},
       org01_open_date    = #{openDate},
       org01_close_date   = #{closeDate},
       org01_open_reason  = #{openReason},
       org01_close_reason = #{closeReason}
 WHERE org01_code_id    = #{orgCodeId}
   AND org01_company_id = #{companyId}
